import { getTableColumns } from 'drizzle-orm';
import { describe, expect, it } from 'vitest';
import { userRecordSchema } from '#lib/schemas/user.js';
import { createAuth } from '../../auth/create-auth.js';
import { createDatabase } from '../create-database.js';
import { account, session, user, verification } from './auth.js';

const tables = { user, session, account, verification };

// The auth tables are generated by `pnpm auth:generate`. These tests fail when
// the generated schema is stale (the better-auth config changed and nobody
// regenerated) or when our hand-written user record drifts from the table.
describe('auth schema', () => {
	it('has every table and column better-auth expects', async () => {
		const auth = createAuth({
			db: createDatabase('postgresql://test:test@localhost:5432/test'),
			secret: 'x'.repeat(40),
			baseURL: 'http://localhost:5173'
		});
		const context = await auth.$context;
		const expected = context.tables as Record<
			string,
			{ modelName: string; fields: Record<string, { fieldName?: string }> }
		>;

		for (const [name, model] of Object.entries(expected)) {
			const table = tables[model.modelName as keyof typeof tables];
			expect(table, `table for ${name}`).toBeDefined();
			const columns = Object.keys(getTableColumns(table));
			const wanted = ['id', ...Object.keys(model.fields)];
			for (const field of wanted) expect(columns, `${name}.${field}`).toContain(field);
		}
	});

	it('describes users with columns that exist', () => {
		const columns = Object.keys(getTableColumns(user));

		for (const field of Object.keys(userRecordSchema.shape)) {
			expect(columns, field).toContain(field);
		}
	});
});
